#[cfg(test)]
mod tests {
    #[allow(unused_imports)]
    use crate::proto::ProtoId;

    /// A guard that rejects every probe would hide a dropped bitmap bit,
    /// so the probes have to reach as many arms as they can.
    const PROBES: &[&[u8]] = &[
        &[],
        &[0u8; 64],
        &[0xff; 64],
        b"GET / HTTP/1.1\r\nHost: h\r\n\r\n",
    ];

    #[test]
    fn udp_port_bitmap_agrees_with_the_match() {
        for v in 0..=u16::MAX {
            let c = super::claimed(&super::UDP_PORT_CLAIMED, v);
            assert_eq!(c, super::UDP_PORT_VALUES.contains(&v), "udp_port {v}");
            for p in PROBES {
                assert!(
                    c || super::by_udp_port_one(v, p).is_none(),
                    "udp_port {v} dispatches past the bitmap"
                );
            }
        }
    }

    #[test]
    fn tcp_port_bitmap_agrees_with_the_match() {
        for v in 0..=u16::MAX {
            let c = super::claimed(&super::TCP_PORT_CLAIMED, v);
            assert_eq!(c, super::TCP_PORT_VALUES.contains(&v), "tcp_port {v}");
            for p in PROBES {
                assert!(
                    c || super::by_tcp_port_one(v, p).is_none(),
                    "tcp_port {v} dispatches past the bitmap"
                );
            }
        }
    }

    /// A parent's field is placed by the spec that binds under it, which
    /// for a hand-written parent is a claim about a table protogen cannot
    /// see. The engine's own table has to agree, or dispatch reads the
    /// wrong bits.
    #[test]
    fn every_parent_field_is_where_the_bindings_read_it() {
        assert_eq!(
            crate::proto::field_of(ProtoId::ATTHdr, "opcode").map(|f| (f.bit_off, f.bit_len)),
            Some((0, 8))
        );
        assert_eq!(
            crate::proto::field_of(ProtoId::Dot11Action, "category")
                .map(|f| (f.bit_off, f.bit_len)),
            Some((0, 8))
        );
        assert_eq!(
            crate::proto::field_of(ProtoId::HCIEventLEMeta, "event")
                .map(|f| (f.bit_off, f.bit_len)),
            Some((0, 8))
        );
        assert_eq!(
            crate::proto::field_of(ProtoId::MobileIP, "type").map(|f| (f.bit_off, f.bit_len)),
            Some((0, 8))
        );
        assert_eq!(
            crate::proto::field_of(ProtoId::Ppp, "proto").map(|f| (f.bit_off, f.bit_len)),
            Some((0, 16))
        );
        assert_eq!(
            crate::proto::field_of(ProtoId::PppoeDisc, "type").map(|f| (f.bit_off, f.bit_len)),
            Some((4, 4))
        );
        assert_eq!(
            crate::proto::field_of(ProtoId::SMHdr, "sm_command").map(|f| (f.bit_off, f.bit_len)),
            Some((0, 8))
        );
    }

    /// The reverse map is what stacking a layer writes, so a port it
    /// names that the gate does not claim would build a packet the
    /// dissector cannot read back.
    #[test]
    fn every_bound_port_is_still_claimed() {
        for id in crate::proto::builtins() {
            if let Some(v) = super::by_udp_port_of(id) {
                assert!(
                    super::claimed(&super::UDP_PORT_CLAIMED, v),
                    "by_udp_port {v}"
                );
            }
            if let Some(v) = super::by_tcp_port_of(id) {
                assert!(
                    super::claimed(&super::TCP_PORT_CLAIMED, v),
                    "by_tcp_port {v}"
                );
            }
        }
    }
}
